/// <summary>
/// Extends SysOperationAutomaticUIBuilder
/// </summary>
class AVACreditLimitGroupAssignmentUIBuilder extends SysOperationAutomaticUIBuilder
{
    private FormControlName creditLimitGroupFieldName;

}

Method.Source:
/// <summary>
/// postBuild method
/// </summary>
public void postBuild()
{
    DialogField creditLimitGroupField;

    super();

    creditLimitGroupField = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(AVACreditLimitGroupAssignmentContract, parmCreditLimitGroup));

    creditLimitGroupFieldName   = creditLimitGroupField.name();

    creditLimitGroupField.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(AVACreditLimitGroupAssignmentUIBuilder, lookupCreditLimitGroupField), this);
}

/// <summary>
/// lookupCreditLimitGroupField method
/// </summary>
/// <param name = "_control">FormStringControl</param>
private void lookupCreditLimitGroupField(FormStringControl _control)
{
    SysTableLookup sysTableLookup = SysTablelookup::newParameters(tableNum(CredManCreditLimitCustGroup), _control);
    Query          query = new Query();

    QueryBuildDataSource qbds = SysQuery::findOrCreateDataSource(query, tableNum(CredManCreditLimitCustGroup));
    SysQuery::findOrCreateRange(qbds, fieldNum(CredManCreditLimitCustGroup, AVACompanyId)).value(SysQuery::value(curExt()));
    sysTableLookup.addLookupfield(fieldNum(CredManCreditLimitCustGroup, CreditLimitId), true);
    sysTableLookup.addLookupfield(fieldNum(CredManCreditLimitCustGroup, AVACompanyId)); 
    sysTableLookup.addLookupfield(fieldNum(CredManCreditLimitCustGroup, Description));
    sysTableLookup.parmQuery(query);

    sysTableLookup.performFormLookup();
}
